#include <bits/stdc++.h>
using namespace std;


vector<string> str;

int isVowel(char ch)
{
    if(ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u')
    return 1;
    return 0;
}


int subString(string s, int n)
{
    int count=0;
    for (int i = 0; i < n; i++)
    {
        string temp = "";
        for (int j = i; j < n; j++)
        {
            temp += s[j];
            if(temp.length() > 1)
            {
                if(isVowel(temp[0]) && !isVowel(temp[temp.length()-1]))
                    count++;
                if(!isVowel(temp[0]) && isVowel(temp[temp.length()-1]))
                    count++;
            }
        }
    }
    return count%1000000007;          
}

int solve(string A) 
{	
    return subString(A, A.length());    
}

 
int main()
{
	string st = "";
    int res = solve(st);
    cout << res;
    return 0;
}
 
